import hashlib
import ipaddress
import json
import os
import re
import stat as stat_module
import sys

# ---------------------------------------------------------------------------
# Contract constants
# ---------------------------------------------------------------------------

MANIFEST_MAX_BYTES = 1024 * 1024          # 1 MiB
LOG_MAX_BYTES = 96 * 1024 * 1024          # 96 MiB
LOG_MAX_LINES = 300000                    # physical lines
LINE_MAX_BYTES = 4096                     # including the LF, when present
PROBE_ID_MAX_CHARS = 200
MAX_SEGMENTS = 2048                       # selected /64s over all windows
DOC_TOP32 = 0x20010DB8                    # 2001:db8::/32
CANARY_HIGH_BIT = 1 << 63
MAX_ADDRESS_CHARS = 45                    # longest legal IPv6 text form

ID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}\Z')
ADDRESS_CHARS = frozenset('0123456789abcdefABCDEF:.')
ROW_KEYS = frozenset(('probe_id', 'received_ms', 'target', 'source',
                      'type', 'code'))
TOP_KEYS = frozenset(('version', 'seed', 'low_count', 'attempts',
                      'spacing_ms', 'timeout_ms', 'windows'))
WINDOW_KEYS = frozenset(('id', 'start_ms', 'scopes'))
SCOPE_KEYS = frozenset(('id', 'prefix', 'subnets'))
CANONICAL_PREFIX = 'ipv6-evidence-v1'

ADDRESS_CACHE_LIMIT = 262144
_address_cache = {}


class Fatal(Exception):
    """A whole-file / argument error: exit 2, empty stdout, stderr note."""


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def _reject_constant(_value):
    raise Fatal('nonfinite JSON number')


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Fatal('duplicate JSON object key %r' % (key,))
        result[key] = value
    return result


def is_int(value):
    """True for JSON integers only: booleans and floats are excluded."""
    return isinstance(value, int) and not isinstance(value, bool)


def int_in_range(value, low, high, label):
    if not is_int(value):
        raise Fatal('%s must be an integer' % label)
    if value < low or value > high:
        raise Fatal('%s must be in [%d, %d]' % (label, low, high))
    return value


def check_id(value, label):
    if not isinstance(value, str):
        raise Fatal('%s must be a string' % label)
    if ID_RE.match(value) is None:
        raise Fatal('%s %r is not a valid identifier' % (label, value))
    return value


def ipv6_value(text):
    """Strict IPv6 text -> 128-bit int inside 2001:db8::/32, else None.

    No zone IDs, no whitespace, no other spellings than the RFC 4291 text
    form accepted by ipaddress (uppercase and embedded dotted quads allowed).
    """
    if not isinstance(text, str):
        return None
    length = len(text)
    if length == 0 or length > MAX_ADDRESS_CHARS:
        return None
    if not ADDRESS_CHARS.issuperset(text):
        return None
    try:
        value = int(ipaddress.IPv6Address(text))
    except (ValueError, TypeError):
        return None
    if (value >> 96) != DOC_TOP32:
        return None
    return value


def cached_ipv6_value(text):
    try:
        return _address_cache[text]
    except KeyError:
        pass
    value = ipv6_value(text)
    if len(_address_cache) < ADDRESS_CACHE_LIMIT:
        _address_cache[text] = value
    return value


def address_text(value):
    """Canonical Python 3.11 spelling of a 128-bit address value."""
    try:
        return _address_cache[value]
    except KeyError:
        pass
    text = str(ipaddress.IPv6Address(value))
    if len(_address_cache) < ADDRESS_CACHE_LIMIT:
        _address_cache[value] = text
    return text


def network_text(base):
    return address_text(base) + '/64'


def int_list(values):
    return '[' + ','.join([str(value) for value in values]) + ']'


def address_list(values):
    return '[' + ','.join(['"%s"' % address_text(value) for value in values]) + ']'


def attempt_list(mask, attempts):
    return '[' + ','.join([str(a) for a in range(attempts) if (mask >> a) & 1]) + ']'


def read_bytes(path, max_bytes, label):
    if path == '-':
        raise Fatal('%s: stdin is not an accepted input' % label)
    try:
        handle = open(path, 'rb')
    except OSError as exc:
        raise Fatal('cannot open %s %r: %s' % (label, path, exc))
    with handle:
        try:
            info = os.fstat(handle.fileno())
        except OSError as exc:
            raise Fatal('cannot stat %s %r: %s' % (label, path, exc))
        if not stat_module.S_ISREG(info.st_mode):
            raise Fatal('%s %r is not a regular file' % (label, path))
        data = handle.read(max_bytes + 1)
    if len(data) > max_bytes:
        raise Fatal('%s %r exceeds the %d byte limit' % (label, path, max_bytes))
    return data


def parse_json_bytes(raw, label):
    if raw.startswith(b'\xef\xbb\xbf'):
        raise Fatal('%s starts with a UTF-8 BOM' % label)
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError as exc:
        raise Fatal('%s is not valid UTF-8: %s' % (label, exc))
    if text.startswith('\ufeff'):
        raise Fatal('%s starts with a BOM' % label)
    try:
        return json.loads(text, object_pairs_hook=_unique_object,
                          parse_constant=_reject_constant)
    except Fatal:
        raise
    except Exception as exc:
        raise Fatal('%s is not valid JSON: %s' % (label, exc))


def canary_iid(seed, window_id, scope_id, net_text):
    payload = ('%s\n%d\n%s\n%s\n%s\n' % (CANONICAL_PREFIX, seed, window_id,
                                         scope_id, net_text)).encode('ascii')
    digest = hashlib.sha256(payload).digest()
    return int.from_bytes(digest[:8], 'big') | CANARY_HIGH_BIT


