                      parse_constant=lambda x: (_ for _ in ()).throw(Bad('nf')))


def isint(v):
    return isinstance(v, int) and not isinstance(v, bool)


def rng(v, lo, hi, what):
    if not isint(v) or v < lo or v > hi:
        raise Bad(what)
    return v


def addr6(text):
    """Return int value if a strict doc-prefix IPv6 text, else None."""
    if not isinstance(text, str):
        return None
    for ch in text:
        if ch in ' \t\r\n\v\f%':
            return None
        if not (ch in '0123456789abcdefABCDEF:.'):
            return None
    try:
        a = ipaddress.IPv6Address(text)
    except Exception:
        return None
    if not a in DOC:
        return None
    return int(a)


def fmt(v):
    return str(ipaddress.IPv6Address(v))


def load_manifest(path):
    raw = open(path, 'rb').read()
    if len(raw) > 1024 * 1024:
